    "question": "How does Mina work through a mechanical problem?",
    "is_question": true,
    "form": "The co-op job card: Customer report, Findings, Parts, Work carried out, Test ride.",
    "object": "Six persistent paper portfolio record cards carrying project evidence.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The sequence comes from Mina’s stated job-card practice and uses her bike inventory, charger contribution and unfinished bracket as its evidence."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The cards organize fields, project pairs, contributions and outcomes, so removing them requires replacing those explanatory relationships."
    },
    "depth": {
      "result": "pass",
      "reason": "The intake stack develops through findings and project inspection into contribution records and a closing evidence review."
    },
    "clipart": {
      "result": "pass",
      "reason": "The central object is a working record grounded in her actual routine rather than a stock engineering emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The plan preserves group attribution and unbuilt status while excluding the team placing, guessed repair count and invented achievements."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The first screen provides Mina’s name, discipline, confirmed charger contribution and direct CV/contact access."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question and concrete contribution use understandable language without inflated engineering claims."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "The plan turns Mina’s co-op job card into five chapters, using six rearranging paper cards to present honestly attributed project evidence. Its greatest weakness is that final opening copy and captions remain deferred, leaving the promised complete page script partly specified as content slots."
